-- 1.1 Districts of Caloocan City
-- --------------------------------------------------------------
CREATE TABLE IF NOT EXISTS districts (
    id          SERIAL       PRIMARY KEY,
    name        VARCHAR(100) NOT NULL UNIQUE,  -- e.g. "District 1 – South Caloocan"
    code        VARCHAR(10)  NOT NULL UNIQUE,  -- D1, D2, D3
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

COMMENT ON TABLE districts IS 'Caloocan City legislative districts. Currently three: South (D1), North (D2), Far North (D3).';

-- 1.2 Barangays — normalises the scattered barangay VARCHAR columns
-- --------------------------------------------------------------
CREATE TABLE IF NOT EXISTS barangays (
    id          SERIAL       PRIMARY KEY,
    name        VARCHAR(150) NOT NULL UNIQUE,  -- canonical name, e.g. "Barangay 1" or "Camarin"
    district_id INTEGER      NOT NULL REFERENCES districts(id) ON DELETE RESTRICT,
    zip_code    VARCHAR(10),
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

COMMENT ON TABLE barangays IS 'Master list of Caloocan City barangays. Acts as FK anchor for all geographic references across the system.';

