-- 3.1 users — link role to system_roles
--     Adds role_id alongside the legacy role varchar.
--     The legacy `role` column is kept as a human-readable snapshot; role_id is the
--     authoritative FK.  Remove `role` varchar in a follow-up migration once all
--     application code reads role_id or joins through system_roles.
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS role_id INTEGER;

-- 3.2 users — link barangay to normalised barangays table
ALTER TABLE users
    ADD COLUMN IF NOT EXISTS barangay_id INTEGER;

-- 3.3 advisories — link to the user who authored it
ALTER TABLE advisories
    ADD COLUMN IF NOT EXISTS author_id INTEGER;

-- 3.4 project_requests — normalised barangay FK
ALTER TABLE project_requests
    ADD COLUMN IF NOT EXISTS barangay_id INTEGER;

-- 3.5 infrastructure_assets — normalised barangay FK
ALTER TABLE infrastructure_assets
    ADD COLUMN IF NOT EXISTS barangay_id INTEGER;

-- 3.6 obo_inspections — normalised barangay FK
ALTER TABLE obo_inspections
    ADD COLUMN IF NOT EXISTS barangay_id INTEGER;

-- ───────────────────────────────────────────────────────────────────────────────────────
-- SECTION 4 — BACK-FILL FK COLUMNS FROM EXISTING STRING DATA
-- ───────────────────────────────────────────────────────────────────────────────────────

-- 4.1 users.role_id  ← match on system_roles.name
UPDATE users u
SET    role_id = sr.id
FROM   system_roles sr
WHERE  u.role = sr.name
  AND  u.role_id IS NULL;

-- 4.2 users.barangay_id  ← case-insensitive match on barangays.name
UPDATE users u
SET    barangay_id = b.id
FROM   barangays b
WHERE  TRIM(UPPER(u.barangay)) = TRIM(UPPER(b.name))
  AND  u.barangay_id IS NULL;

-- 4.3 project_requests.barangay_id
UPDATE project_requests pr
SET    barangay_id = b.id
FROM   barangays b
WHERE  TRIM(UPPER(pr.barangay)) = TRIM(UPPER(b.name))
  AND  pr.barangay_id IS NULL;

-- 4.4 infrastructure_assets.barangay_id
UPDATE infrastructure_assets ia
SET    barangay_id = b.id
FROM   barangays b
WHERE  TRIM(UPPER(ia.barangay)) = TRIM(UPPER(b.name))
  AND  ia.barangay_id IS NULL;

-- 4.5 obo_inspections.barangay_id
UPDATE obo_inspections oi
SET    barangay_id = b.id
FROM   barangays b
WHERE  TRIM(UPPER(oi.barangay)) = TRIM(UPPER(b.name))
  AND  oi.barangay_id IS NULL;

-- 4.6 environmental_context already has barangay_id as INTEGER;
--     however it currently references nothing.  We need to convert it so that
--     the value stored in barangay_id maps to barangays.id.
--     Since prior data format was a numeric id that had no stable reference,
--     we look up by matching any existing name-based string if the old id matches.
--     ⚠  If existing barangay_id values were arbitrary integers (not barangay PK values),
--        NULL them out first and let operators re-assign via the admin UI.
UPDATE environmental_context ec
SET    barangay_id = b.id
FROM   barangays b
WHERE  CAST(ec.barangay_id AS TEXT) = CAST(b.id AS TEXT);  -- safe if old ids match new ones

