-- ── users ──────────────────────────────────────────────────────────────────────────────

-- Link role to system_roles
ALTER TABLE users
    ADD CONSTRAINT fk_users_role_id
        FOREIGN KEY (role_id) REFERENCES system_roles(id) ON DELETE RESTRICT;

-- Link barangay to normalised lookup
ALTER TABLE users
    ADD CONSTRAINT fk_users_barangay_id
        FOREIGN KEY (barangay_id) REFERENCES barangays(id) ON DELETE SET NULL;

-- Self-referential suspension (already exists in ORM; enforce at DB level)
-- NOTE: PostgreSQL allows FK on same table.
ALTER TABLE users
    DROP CONSTRAINT IF EXISTS fk_users_suspended_by;
ALTER TABLE users
    ADD CONSTRAINT fk_users_suspended_by
        FOREIGN KEY (suspended_by) REFERENCES users(id) ON DELETE SET NULL;

-- ── notifications ──────────────────────────────────────────────────────────────────────

-- Notifications belong to a user; if user is deleted, delete their notifications.
ALTER TABLE notifications
    DROP CONSTRAINT IF EXISTS fk_notifications_user_id;
ALTER TABLE notifications
    ADD CONSTRAINT fk_notifications_user_id
        FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE;

-- ── reports ────────────────────────────────────────────────────────────────────────────

-- Reports are civic records; preserve them even if the citizen account is deleted.
ALTER TABLE reports
    DROP CONSTRAINT IF EXISTS fk_reports_user_id;
ALTER TABLE reports
    ADD CONSTRAINT fk_reports_user_id
        FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL;

