-- ───────────────────────────────────────────────────────────────────────────────────────
-- SECTION 9 — CHECK CONSTRAINTS (guarding the polymorphic document pattern)
-- ───────────────────────────────────────────────────────────────────────────────────────

-- system_documents uses a polymorphic reference (target_model + target_id).
-- A true FK is not possible across multiple tables; instead we constrain the
-- string to only the known entity names, preventing silent data corruption.

ALTER TABLE system_documents
    DROP CONSTRAINT IF EXISTS ck_sysdoc_target_model;
ALTER TABLE system_documents
    ADD CONSTRAINT ck_sysdoc_target_model
        CHECK (target_model IN (
            'WorkOrder',
            'ProjectRequest',
            'ProcurementRequest',
            'OBOInspection',
            'Report',
            'InfrastructureAsset',
            'MaintenanceHistory'
        ));

-- advisory priority and status value guards
ALTER TABLE advisories
    DROP CONSTRAINT IF EXISTS ck_advisories_priority;
ALTER TABLE advisories
    ADD CONSTRAINT ck_advisories_priority
        CHECK (priority IN ('low', 'medium', 'high', 'critical'));

-- work order status guard
ALTER TABLE work_orders
    DROP CONSTRAINT IF EXISTS ck_wo_status;
ALTER TABLE work_orders
    ADD CONSTRAINT ck_wo_status
        CHECK (status IN ('open', 'assigned', 'in_progress', 'completed', 'cancelled'));

ALTER TABLE work_orders
    DROP CONSTRAINT IF EXISTS ck_wo_priority;
ALTER TABLE work_orders
    ADD CONSTRAINT ck_wo_priority
        CHECK (priority IN ('low', 'normal', 'high', 'critical'));

-- ───────────────────────────────────────────────────────────────────────────────────────
-- SECTION 10 — PRE-COMMIT VALIDATION (orphan row audit)
-- Run these SELECT statements and confirm all counts = 0 before COMMIT.
-- ───────────────────────────────────────────────────────────────────────────────────────

-- 10.1 Users without a role_id match
SELECT 'users_without_role_id' AS check_name, COUNT(*) AS orphan_count
FROM   users u
WHERE  u.role_id IS NULL AND u.role IS NOT NULL;

-- 10.2 Users with a role that has no corresponding system_role
SELECT 'users_with_unknown_role' AS check_name, COUNT(*) AS orphan_count
FROM   users u
LEFT   JOIN system_roles sr ON u.role = sr.name
WHERE  sr.id IS NULL;

-- 10.3 Advisories without an author (acceptable if historical; informational only)
SELECT 'advisories_without_author' AS check_name, COUNT(*) AS orphan_count
FROM   advisories
WHERE  author_id IS NULL;

-- 10.4 environmental_context rows not matched to a barangay
SELECT 'env_context_unlinked' AS check_name, COUNT(*) AS orphan_count
FROM   environmental_context
WHERE  barangay_id IS NULL;

-- 10.5 work_orders with district_id not in districts table
SELECT 'wo_invalid_district' AS check_name, COUNT(*) AS orphan_count
FROM   work_orders wo
LEFT   JOIN districts d ON wo.district_id = d.id
WHERE  wo.district_id IS NOT NULL AND d.id IS NULL;

-- 10.6 Reports with a deleted user_id (stale references)
SELECT 'reports_user_orphan' AS check_name, COUNT(*) AS orphan_count
FROM   reports r
LEFT   JOIN users u ON r.user_id = u.id
WHERE  r.user_id IS NOT NULL AND u.id IS NULL;

-- 10.7 boq_items with invalid procurement_request_id
SELECT 'boq_orphan_procurement' AS check_name, COUNT(*) AS orphan_count
FROM   boq_items b
LEFT   JOIN procurement_requests pr ON b.procurement_request_id = pr.id
WHERE  pr.id IS NULL;

